"""Release notes generated by release/cliff.toml from real commits."""

import shutil
import subprocess
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[2]


def git(repo, *args):
    """Run git in the temporary repository."""
    subprocess.run(["git", "-C", str(repo), *args], check=True, capture_output=True, text=True)


def test_also_footers_add_entries_to_their_sections(tmp_path):
    """One commit with Also-* footers produces one entry per change, in the right sections."""
    if shutil.which("git-cliff") is None:
        pytest.fail("git-cliff is required for release note tests; install it as in the zaigr-dev setup")
    git(tmp_path, "init", "-q")
    git(tmp_path, "config", "user.email", "test@example.com")
    git(tmp_path, "config", "user.name", "Test")
    commits = [
        "fix: resolve localhost inside the VM",
        (
            "feat: bundle slirp4netns so hosts no longer need the package\n\n"
            "This commit contains two features that could not be separated safely.\n\n"
            "Also-added: track all bundled dependency versions with make deps-check\n"
            "Also-fixed: kernel updates reach existing projects without a rebuild\n"
            "Co-Authored-By: Someone <someone@example.com>"
        ),
        "chore: tidy build scripts\n\nAlso-changed: ignored because chore commits are omitted",
    ]
    for message in commits:
        git(tmp_path, "commit", "-q", "--allow-empty", "-m", message)

    notes = subprocess.run(
        ["git-cliff", "--config", str(REPO_ROOT / "release" / "cliff.toml")],
        cwd=tmp_path, check=True, capture_output=True, text=True,
    ).stdout

    sections = {}
    current = None
    for line in notes.splitlines():
        if line.startswith("### "):
            current = line[4:]
            sections[current] = []
        elif current and line.startswith("- "):
            sections[current].append(line[2:])
    assert sections == {
        "Added": [
            "Bundle slirp4netns so hosts no longer need the package",
            "Track all bundled dependency versions with make deps-check",
        ],
        "Fixed": [
            "Resolve localhost inside the VM",
            "Kernel updates reach existing projects without a rebuild",
        ],
    }, notes
